"""Write work/holds_v2.json to frontend/lib/wall/holds_v2.dart and export
the wall photo to frontend/assets/spray_wall_v2.jpg."""
import json
import sys
from pathlib import Path

import cv2

ROOT = Path(__file__).parent
WORK = ROOT / "work"
FRONT = ROOT.parent / "frontend"

holds = json.loads((WORK / "holds_v2.json").read_text())
lines = [
    "// GENERATED by tools/export_holds.py from the July 2026 wall photo.",
    "// Do not edit by hand: re-run tools/merge_holds.py + export_holds.py.",
    "//",
    "// Hold outlines for wall 2, in pixels of the 5712x4284 photo, as flat",
    "// [x0, y0, x1, y1, ...] lists. The list index is the hold id stored in",
    "// climbs, so never reorder or remove entries once climbs exist; append",
    "// new holds at the end instead.",
    "",
    "const List<List<int>> holdsV2Data = [",
]
for h in holds:
    flat = [v for p in h for v in p]
    lines.append("  [" + ", ".join(str(int(v)) for v in flat) + "],")
lines.append("];")
(FRONT / "lib/wall/holds_v2.dart").write_text("\n".join(lines) + "\n")
print("wrote", len(holds), "holds")

if "--image" in sys.argv:
    img = cv2.imread(str(WORK / "wall_full.png"))
    cv2.imwrite(str(FRONT / "assets/spray_wall_v2.jpg"), img, [cv2.IMWRITE_JPEG_QUALITY, 82,
                                                             cv2.IMWRITE_JPEG_OPTIMIZE, 1])
    print("wrote image", (FRONT / "assets/spray_wall_v2.jpg").stat().st_size // 1024, "KB")
